import type { Metadata } from "next"
import { getDictionary } from "@/lib/dictionary"
import { HTML_LANG, OG_LOCALE, defaultLocale, type Locale } from "@/lib/i18n"
import { marketplaceReviews } from "@/lib/links"
import { PRICING, type Billing } from "@/lib/pricing"
import { plain } from "@/lib/rich"
import { SECTIONS, routeLocales, routePath, type Route } from "@/lib/routes"
import { COMPANY, SITE, SITE_URL } from "@/lib/site"
import { fill } from "@/lib/text"

/** Social preview image of a language (generated by scripts/build-media.mjs, 1200×630). */
export const ogImagePath = (lang: Locale) => `/og/${lang}.png`

type PageMetadataInput = {
  lang: Locale
  route: Route
  title: string
  description: string
  noindex?: boolean
}

/** Canonical + hreflang alternates of a route — only the languages it exists in (x-default = default locale, or the
 *  route's first language when it has no default-locale version). */
export function alternates(lang: Locale, route: Route): Metadata["alternates"] {
  const langs = routeLocales(route)
  const fallback = langs.includes(defaultLocale) ? defaultLocale : langs[0]
  return {
    canonical: routePath(lang, route),
    languages: {
      ...Object.fromEntries(langs.map((l) => [l, routePath(l, route)])),
      "x-default": routePath(fallback, route),
    },
  }
}

/** Title, description, canonical, hreflang, Open Graph and Twitter card of a page. */
export function buildPageMetadata({ lang, route, title, description, noindex }: PageMetadataInput): Metadata {
  const dict = getDictionary(lang)
  const url = routePath(lang, route)
  const image = { url: ogImagePath(lang), width: 1200, height: 630, alt: dict.meta.ogImageAlt }
  return {
    title,
    description,
    alternates: alternates(lang, route),
    openGraph: {
      type: "website",
      locale: OG_LOCALE[lang],
      alternateLocale: routeLocales(route)
        .filter((l) => l !== lang)
        .map((l) => OG_LOCALE[l]),
      siteName: SITE.name,
      url,
      title,
      description,
      images: [image],
    },
    twitter: { card: "summary_large_image", title, description, images: [image] },
    robots: noindex ? { index: false, follow: true } : undefined,
  }
}

/* ── structured data ─────────────────────────────────────────────────── */

const ORG_ID = `${COMPANY.website}/#organization`

export function buildOrganizationJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "Organization",
    "@id": ORG_ID,
    name: COMPANY.name,
    url: COMPANY.website,
    logo: `${SITE_URL}${COMPANY.logo}`,
    email: COMPANY.email,
    telephone: COMPANY.phone,
    vatID: COMPANY.vatId,
    address: {
      "@type": "PostalAddress",
      streetAddress: COMPANY.address.street,
      postalCode: COMPANY.address.postalCode,
      addressLocality: COMPANY.address.city,
      addressCountry: COMPANY.address.country,
    },
    sameAs: [COMPANY.linkedin],
  }
}

/** WebSite node: name and language of this language version, published by the company. */
export function buildWebSiteJsonLd(lang: Locale) {
  return {
    "@context": "https://schema.org",
    "@type": "WebSite",
    "@id": `${SITE_URL}${routePath(lang)}#website`,
    name: SITE.name,
    url: `${SITE_URL}${routePath(lang)}`,
    inLanguage: HTML_LANG[lang],
    publisher: { "@id": ORG_ID },
  }
}

/** How often each plan is billed (ISO 8601 duration). */
const BILLING_DURATION: Record<Billing, string> = { monthly: "P1M", yearly: "P1Y" }

export function buildSoftwareApplicationJsonLd(lang: Locale) {
  const dict = getDictionary(lang)
  const t = dict.home.pricing
  return {
    "@context": "https://schema.org",
    "@type": "SoftwareApplication",
    name: SITE.name,
    url: `${SITE_URL}${routePath(lang)}`,
    description: dict.meta.description,
    applicationCategory: "BusinessApplication",
    applicationSubCategory: dict.meta.appCategory,
    operatingSystem: "Web",
    inLanguage: HTML_LANG[lang],
    image: `${SITE_URL}${ogImagePath(lang)}`,
    publisher: { "@id": ORG_ID },
    sameAs: [marketplaceReviews(lang)],
    // The price is per month and bexio company in both plans; only how often it is billed differs.
    offers: (Object.keys(PRICING.company) as Billing[]).map((billing) => ({
      "@type": "Offer",
      name: `${SITE.name} – ${t.billing[billing].label}`,
      url: `${SITE_URL}${routePath(lang, "home", SECTIONS.pricing)}`,
      price: PRICING.company[billing],
      priceCurrency: "CHF",
      priceSpecification: {
        "@type": "UnitPriceSpecification",
        price: PRICING.company[billing],
        priceCurrency: "CHF",
        unitText: t.unit,
        referenceQuantity: { "@type": "QuantitativeValue", value: 1, unitCode: "MON" },
        billingDuration: BILLING_DURATION[billing],
      },
    })),
  }
}

/** FAQ items with prices filled in – shared by the page and its JSON-LD. */
export function faqItems(lang: Locale) {
  return Object.entries(getDictionary(lang).home.faq.items).map(([id, item]) => ({
    id,
    question: item.question,
    answer: fill(item.answer, PRICING.company),
  }))
}

export function buildFaqJsonLd(lang: Locale) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    inLanguage: HTML_LANG[lang],
    mainEntity: faqItems(lang).map((item) => ({
      "@type": "Question",
      name: plain(item.question),
      acceptedAnswer: { "@type": "Answer", text: plain(item.answer) },
    })),
  }
}

type BreadcrumbItem = { name: string; route: Route }

/** The demo video as a schema.org VideoObject (the /<lang>/demo/ page): lets search engines show it as a video result. */
export function buildDemoVideoJsonLd(lang: Locale, video: { src: string; uploadDate: string; duration: string }) {
  const t = getDictionary(lang).demoPage
  return {
    "@context": "https://schema.org",
    "@type": "VideoObject",
    name: t.title,
    description: t.description,
    thumbnailUrl: `${SITE_URL}${video.src}-poster.webp`,
    contentUrl: `${SITE_URL}${video.src}.mp4`,
    embedUrl: `${SITE_URL}${routePath(lang, "demo")}`,
    uploadDate: video.uploadDate,
    duration: video.duration,
    inLanguage: HTML_LANG[lang],
    publisher: { "@id": ORG_ID },
  }
}

export function buildBreadcrumbJsonLd(lang: Locale, items: BreadcrumbItem[]) {
  const all = [{ name: getDictionary(lang).meta.home, route: "home" as Route }, ...items]
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: all.map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: plain(item.name).replace(/­/g, ""),
      item: `${SITE_URL}${routePath(lang, item.route)}`,
    })),
  }
}
